def split_sms(message):
    if len(message) <= 160:
        return [message]
    parts = []
    start = 0
    while start < len(message):
        parts.append(message[start:start + 153])
        start += 153
    return parts

def split_sms(message):
    if len(message) <= 160:
        return [message]
    full, rest = divmod(len(message), 153)
    count = full + (1 if rest else 0)
    return [message[n * 153:(n + 1) * 153] for n in range(count)]

